// moving averages
export function movingAvg(xs, k) {
  const out = [];
  for (let i = 0; i < xs.length - 1; i++) {
    const w = xs.slice(Math.max(0, i - k + 1), i + 1);
    out.push(w.reduce((a, b) => a + b, 0) / w.length);
  }
  return out;
}

export function pairs(xs) {
  const out = [];
  for (let i = 0; i < xs.length - 1; i++) {
    out.push([xs[i], xs[i + 1]]);
  }
  return out;
}

